class Solution { public:
    int longestCycle(vector<int>& edges) {
        int n=edges.size(),ans=-1,stamp=0;
        vector<int> seen(n,0),depth(n,0);
        for(int i=0;i<n;++i)if(!seen[i]){
            ++stamp;int u=i,d=0;
            while(u!=-1 && !seen[u]){seen[u]=stamp;depth[u]=d++;u=edges[u];}
            if(u!=-1 && seen[u]==stamp)ans=max(ans,d-depth[u]);
        }
        return ans;
    }
};
